service.method:

DELETE FROM SBALN
WHERE CTRL_CODE=${CTRL_CODE}
AND COMPANY_CODE = ${COMPANY_CODE}
AND HOUSE_CODE = ${session.HOUSE_CODE}
AND CTRL_PERSON_ID=${USER_ID}


UPDATE SUSMT
SET CTRL_CODE = ${CTRL_CODE}
WHERE USER_ID = ${USER_ID} 
AND COMPANY_CODE = ${COMPANY_CODE}
AND HOUSE_CODE = ${session.HOUSE_CODE}


UPDATE SBALN
SET REPRESENT_CTRL = (CASE WHEN ${REPRESENT_CTRL} = '1' THEN 'Y' 
                           WHEN ${REPRESENT_CTRL} = '0' THEN 'N' END) 
WHERE CTRL_CODE=${CTRL_CODE} 
AND COMPANY_CODE = ${COMPANY_CODE}
AND CTRL_PERSON_ID=${USER_ID}
AND HOUSE_CODE = ${session.HOUSE_CODE}
